<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span>Statement of Accounts</span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

        <div class="d-flex align-items-center me-4 mt-2 my-4 position-relative w-100" v-if="!loading_spinner">
            <!-- Centered Header -->
            <div class="flex-grow-1 text-center">
                <h5 class="m-0">STATEMENT OF ACCOUNTS </h5>
            </div>
        </div>


       <div class="d-flex justify-content-between align-items-center mt-2 mb-4 w-100" v-if="!loading_spinner">

    <!-- LEFT SIDE -->
    <div class="text-start text-dark" >
        <h6 class="m-0">
            {{ statementName }} &nbsp; &nbsp;  Balance : {{ finalBalance }}
        </h6>
    </div>

    <!-- RIGHT SIDE -->
    <div class="text-end text-dark">
        <h6 class="m-0">
 {{ statementIssuer }} &nbsp; &nbsp; Total  {{ totalReceived }} 
        </h6>
    </div>

</div>


      <!-- loading spinner starts -->
        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->
        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="statement" :columns="columns" :options="table_option">
                            <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3" @click="openEditModal(props.row)" data-bs-toggle="modal" :data-bs-target="'#edit-conversion-factor-modal'">
                                    <svg
                                        xmlns="http://www.w3.org/2000/svg"
                                        width="24"
                                        height="24"
                                        viewBox="0 0 24 24"
                                        fill="none"
                                        stroke="currentColor"
                                        stroke-width="2"
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        class="feather feather-edit-3"
                                    >
                                        <path d="M12 20h9"></path>
                                        <path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"></path>
                                    </svg>
                                </a>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>


<script setup>
import { onMounted, ref, inject, computed } from 'vue';
import axios from 'axios';
import { useMeta } from '@/composables/use-meta';

useMeta({ title: 'Statement of Accounts' });
    import { useRouter, useRoute } from 'vue-router';
    const router = useRouter();
    const route = useRoute(); 
    const bin_card_id = route.params.bin_card_id;
const showMessage = inject('showMessage');
const showError = inject('showError');
const formatDate = inject('formatDate');
const tableShimmer = inject('tableShimmer');

const loading_spinner = ref(false);
const statement = ref([]);
const statementName = ref('');
const statementIssuer = ref('');

const columns = ref(['SNo', 'date', 'ref_no','remark','Dr', 'Cr', 'balance']);

const table_option = ref({
    perPage: 20,
    perPageValues: [20, 50, 100],
    skin: 'table table-hover table-striped',
    columnsClasses: { actions: 'actions text-center' },
    sortable: ['SNo', 'date', 'ref_no'],
    sortIcon: {
        base: 'sort-icon-none',
        up: 'sort-icon-asc',
        down: 'sort-icon-desc',
    },
    pagination: { nav: 'scroll', chunk: 5 },
    texts: {
        count: 'Showing {from} to {to} of {count}',
        filter: '',
        filterPlaceholder: 'Search...',
        limit: 'Results:',
    },
    resizableColumns: false,
});

const axiosInstance = axios.create({
    baseURL: process.env.VUE_APP_API_BASE_URL
});

const formatNumber = (value) => {
    return new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value);
};

const finalBalance = ref('0.00');
const totalReceived = ref('0.00');
const totalIssued = ref('0.00');


const getStatement = async () => {
    loading_spinner.value = true;

    try {
        const response = await axiosInstance.get(
            `bin-cards?no_store_item=1&bincard_id=${bin_card_id}`
        );
        const data = response.data[0];
        statementName.value = data.name || '';
        statementIssuer.value = data.issuer?.name || 'N/A';

        let runningBalance = 0;
        let totalReceivedAmount = 0;
        let totalIssuedAmount = 0;

        statement.value = data.items.map((item, index) => {
            const received = parseFloat(item.received) || 0;
            const issued = parseFloat(item.issued) || 0;

            totalReceivedAmount += received;
            totalIssuedAmount += issued;
            runningBalance += received - issued;

            return {
                id: item.id,
                SNo: index + 1,
                date: formatDate(item.date),
                ref_no: item.ref_no || '--',
                Dr: received ? formatNumber(received) + ' ' + (data.unit || '') : '--',
                Cr: issued ? formatNumber(issued) + ' ' + (data.unit || '') : '--',
                balance: formatNumber(runningBalance) + ' ' + (data.unit || ''),
                remark: item.remark || '--',
                authorized_by: item.issuer?.name || 'N/A'
            };
        });

        finalBalance.value =
            formatNumber(runningBalance) + ' ' + (data.unit || '');

        totalReceived.value =
            formatNumber(totalReceivedAmount) + ' ' + (data.unit || '');

        totalIssued.value =
            formatNumber(totalIssuedAmount) + ' ' + (data.unit || '');

    } catch (error) {
        console.log(error)
        showError(error.message);
    } finally {
        loading_spinner.value = false;
    }
};


onMounted(() => {
    getStatement();
});
</script>
